# Resume flow after transient error: use persisted resume_token
resume_token = load_checkpoint(user_id)
stream = client.chat.stream(messages, resume_token=resume_token)
for ev in stream:
    if ev.resume_token:
        save_checkpoint(user_id, ev.resume_token)
    if ev.type == "message":
        stream.ack(ev.seq)
